                line = br.readLine();
            }
            if (line == null) break;
            st = new StringTokenizer(line);
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());

            if (A[u] > A[v]) {
                adj[u].add(v);
            } else if (A[v] > A[u]) {
                adj[v].add(u);
            }
        }

        memo = new int[S + 1];
        Arrays.fill(memo, -1);

        int ans = dfs(P);
        System.out.println(ans);
    }

    static int dfs(int u) {
        if (memo[u] != -1) {
            return memo[u];
        }

        int maxLen = 0;
        for (int v : adj[u]) {
            maxLen = Math.max(maxLen, 1 + dfs(v));
        }

        return memo[u] = maxLen;
    }
}
